/** A kill condition (E3). */
export interface QuestKill {
  /** The goal marker. */
  goal: QuestGoalData | null;
  /** The mover (0 = unused slot). */
  mover: number;
  /** The count. */
  num: number;
}

/** A party or guild condition (raw directive values). */
export interface QuestPartyCond {
  /** 0 `==`, 1 `>=`, -1 `<=`. */
  comp: number;
  /** Leader only. */
  leader: number;
  /** The mode. */
  mode: number;
  /** The number. */
  num: number;
}

/** The patrol end condition (E2). */
export interface QuestPatrol {
  /** `PATROL_DESTINATION_ID_nnnn` key into `patrol_destinations`. */
  destination: number | null;
  /** The goal marker. */
  goal: QuestGoalData | null;
  /** `SetPatrolZoneName`. */
  name: string;
  /** The normalised rectangle. */
  rect: [number, number, number, number];
  /** The world. */
  world: number;
}

/** The previous-quest condition (B1). */
export interface QuestPrevious {
  /** 6 slots, 0 = unused. */
  quests: number[];
  /** The type. */
  type: number;
}

/** One reward item. */
export interface QuestRewardItem {
  /** The ability option. */
  ability_option: number;
  /** The bind flag. */
  bind: number;
  /** The item. */
  item: number;
  /** A job or an item. */
  job_or_item: number;
  /** The count. */
  num: number;
  /** -1 any, 0 male, 1 female. */
  sex: number;
  /** The type. */
  type: number;
}

/** The rewards (`null` when hidden by `SetEndRewardHide(1)`). */
export interface QuestRewards {
  /** `[min, max]` exp. */
  exp: [number, number];
  /** `[min, max]` gold. */
  gold: [number, number];
  /** The items. */
  items: QuestRewardItem[];
  /** Raises the pet level. */
  pet_levelup: boolean;
  /** `[min, max]` PK value. */
  pk_value: [number, number];
  /** Skill points. */
  skill_point: number;
  /** The teleport. */
  teleport: QuestTeleport | null;
  /** TSP. */
  tsp: number;
}

/** One described state. */
export interface QuestStateDesc {
  /** The `SetDesc` text. */
  desc: string;
  /** 0..=15. */
  state: number;
}

/** A teleport reward. */
export interface QuestTeleport {
  /** The position. */
  pos: [number, number, number];
  /** The world. */
  world: number;
}

/** `quests` (lazy): the quest definitions, the NPC links and the destination names. */
export interface QuestsBundle {
  /** `PatrolDestination.txt.txt`. */
  patrol_destinations: Record<string, unknown>;
  /** `QuestDestination.txt.txt`. */
  quest_destinations: Record<string, unknown>;
  /** NPC key (lower case) to the quests it completes. */
  quest_dst: Record<string, number[]>;
  /** NPC key (lower case) to the quests it gives, file order. */
  quest_src: Record<string, number[]>;
  /** The quests in ascending id order (empty in this data set). */
  quests: QuestClientDef[];
}

/** One rainbow race NPC marker. */
export interface RainbowMarkerDto {
  /** The running record index = the sprite index in `theme/texmaprainbow_npc.inc`. */
  frame: number;
  /** The continent map number the `map_pos` applies on. */
  map: number;
  /** Position on the continent map. */
  map_pos: [number, number];
  /** Width and height. */
  size: [number, number];
  /** Position on the whole-world map. */
  total_pos: [number, number];
}

/** One random-option item (`RANDOMOPTITEM`). */
export interface RandomOptItemDef {
  /** The id. */
  id: number;
  /** The level. */
  level: number;
  /** The name (IDS key resolved). */
  name: string;
  /** `(DST, adjust)` pairs. */
  params: [number, number][];
  /** The probability. */
  prob: number;
}

/** One destination parameter of a block with its possible values. */
export interface RandomOptionDst {
  /** `DST_*`. */
  dst: number;
  /** The probability of this destination within the block (raw). */
  n: number;
  /** `(value, probability)` pairs (raw probabilities, 1,000,000,000 in total). */
  values: [number, number][];
}

/** One block of the file. */
export interface RandomOptionGroup {
  /** The probability of one option. */
  a: number;
  /** The probability of two options. */
  b: number;
  /** The probability of three options. */
  c: number;
  /** The destinations in file order. */
  dsts: RandomOptionDst[];
  /** The block keyword (`Awakening`, `Blessing`, `SystemPet`, `EatPet`). */
  kind: string;
}

/** `resdata-layouts`: 365 applets with 2,809 controls. */
export interface ResdataBundle {
  /** The applets in file order. */
  applets: AppletRow[];
}

/** One bonus of a set. */
export interface SetAvail {
  /** The adjustment. */
  adj: number;
  /** `DST_*`. */
  dst: number;
  /** The number of equipped pieces that activates it. */
  equiped: number;
}

/** One piece of a set: the item and the `PARTS_*` slot it occupies. */
export interface SetElem {
  /** The item. */
  item: number;
  /** `PARTS_*`. */
  parts: number;
}

/** One row of `Setitem`: `Acc Block HPRate AtkRate Stats` for `+1 ..= +10`. */
export interface SetItemAvail {
  /** `nAdded`. */
  added: number;
  /** `nAttackPowerRate` (custom 4th column, `__BETTER_ARMOR_BONUS`). */
  attack_power_rate: number;
  /** `nBlock`. */
  block: number;
  /** `nHitRate`. */
  hit_rate: number;
  /** `nMaxHitPointRate`. */
  max_hit_point_rate: number;
}

/** One armor set (`CSetItem`). */
export interface SetItemDef {
  /** The bonuses, sorted by `equiped` (exchange sort). */
  avail: SetAvail[];
  /** The pieces (at most 8). */
  elems: SetElem[];
  /** The set id. */
  id: number;
  /** The set name (IDS key resolved). */
  name: string;
}

/** One sfx entry (`mdlDyna.inc` section `sfx`). */
export interface SfxRow {
  /** `MD_*` view distance class. */
  distant: number;
  /** The `.sfx` file as a canonical path under `sfx/`, `null` when it does not exist. */
  file: string | null;
  /** `XI_*`. */
  id: number;
  /** The entry name. */
  name: string;
  /** The render flag (skipped by the "SFX render off" option unless 1). */
  render_flag: number;
  /** The initial scale. */
  scale: number;
  /** The attached sound: a bare file name under `sound/` (44 §5.2), `null` when there is none. */
  sound: string | null;
}

/** `sfx-table`: the effect models by `XI_` id. */
export interface SfxTableBundle {
  /** The sfx entries in ascending id order. */
  sfx: RowTable<SfxRow>;
}

/** The skill-point costs of `Constant.inc` per skill kind. */
export interface SkillPointCosts {
  /** `JTYPE_EXPERT` (default 2). */
  expert_sp: number;
  /** Every other job type (default 3). */
  pro_sp: number;
  /** `JTYPE_BASE` (default 1). */
  vag_sp: number;
}

/** `skills`: skills, party skills, the add-skill levels and the skills of each job. */
export interface SkillsBundle {
  /** `job_skills[job]`: the skill ids of each job (32 jobs), ordered by the required level. */
  job_skills: number[][];
  /** `propSkillAdd` rows (`SA_*`), the per-level numbers of every skill. */
  levels: RowTable<AddSkillProp>;
  /** `propTroupeSkill` rows (`ST_*`). */
  party_skills: RowTable<Omit<ItemProp, "name_key" | "description_key">>;
  /** `propSkill` rows (`SI_*`). */
  skills: RowTable<Omit<ItemProp, "name_key" | "description_key">>;
}

/**
 * `sounds`: `SND_`/`VOC_` id to `sound/<file>` (a canonical path), `null` = the file is missing, `""` =
 * silent. An id that the file does not define is absent.
 */
export interface SoundsBundle {
  /** id to file. */
  sounds: Record<string, unknown>;
}

/** `tables`: the small rule tables the client needs. */
export interface TablesBundle {
  /** The skill-point costs. */
  constants: SkillPointCosts;
  /** The couple tables. */
  couple: CoupleSection;
  /** The emote icons (`propMotion.txt`). */
  emotes: MotionProp[];
  /** The experience tables. */
  exp: ExpSection;
  /** The generic event titles and times. */
  generic_events: GenericEventRow[];
  /** The guild tables. */
  guild: GuildSection;
  /** `GUD_*` to the guild rank name. */
  guild_appellations: Record<string, unknown>;
  /** The starting equipment (`jobItem.inc`; the begin items stay server-only). */
  job_items: JobItemsRow[];
  /** The jobs. */
  jobs: JobRow[];
  /** `lordevent.inc`: the rate lists of the lord's event window (older fixtures lack the field). */
  lord_events: LordEventTables;
  /** The lord skills. */
  lord_skills: LordSkill[];
  /** The PK settings. */
  pk: PkSection;
  /** `SRT_*` to the structure name. */
  structures: Record<string, unknown>;
  /** `teleport16.inc`. */
  teleports16: Teleport16Row[];
}

/** One entry of `teleport16.inc` (the 16-level teleporter window). */
export interface Teleport16Row {
  /** The boss mover (0 = none). */
  boss: number;
  /** The boss drops the window shows (empty until `propMoverEx` is loaded). */
  boss_drops: number[];
  /** The class column. */
  class: number;
  /** The cooldown. */
  cooldown: number;
  /** The description. */
  desc: string;
  /** The preview image (a bare file name). */
  image: string;
  /** Maximum level (`max < min` is `MAX_LEGEND_LEVEL` = 129 on the client). */
  max_level: number;
  /** Minimum level. */
  min_level: number;
  /** The name. */
  name: string;
  /** The destination position. */
  pos: [number, number, number];
  /** The destination world. */
  world: number;
}

/** `terrain`: the terrain texture table in file order. */
export interface TerrainBundle {
  /** The rows. */
  textures: TerrainTexture[];
}

/** One `Terrain.inc` row. */
export interface TerrainTexture {
  /** The texture: a bare file name under `world/texture/`. */
  file: string;
  /** The innermost group name, `""` outside any group. */
  folder: string;
  /** The second number of the row. */
  frames: number;
  /** The enclosing `"name" N` group headers, outermost first; the water frame sets are rebuilt from them. */
  group_path: [string, number][];
  /** The texture id the `.lnd` layers use. */
  id: number;
  /** The last string of the row (unused). */
  sound: string;
}

/** One `textClient.inc` entry. */
export interface TextRow {
  /** ARGB colour. */
  color: number;
  /** The text id (`TID_*`). */
  id: number;
  /** The format string (`%s`/`%d` placeholders), double quotes removed. */
  text: string;
}

/** `texts`: the text table, the emoticon commands and the NPC dialog lines. */
export interface TextsBundle {
  /** `WorldDialog.txt` lines (line `n` is dialog string `n`). */
  dialog: string[];
  /** `textEmotion.txt`. */
  emotions: EmotionRow[];
  /** The `GETTEXT` bound: `getText(tid)` is `"error"` for `tid >= size`, `""` for a hole. */
  size: number;
  /** The non-empty texts in ascending id order. */
  tids: RowTable<TextRow>;
}

/** One ticket of `ticket.inc` as the client's item dispatch needs it (`CTicketProperty` + `CLayerProperty`, R24 of Plan/45 §9.5). */
export interface TicketRow {
  /** `GetExpanedLayer( world )` of `layer.inc`: the layers `-expand ..= 0` the holder may enter (0 without a line). */
  expand: number;
  /** The ticket item (`II_*`). */
  item: number;
  /** The world the ticket opens (`WI_*`). */
  world: number;
}

/** `ui-atlases`: all 39 atlas descriptors by the canonical path of their `.inc`. */
export interface UiAtlasesBundle {
  /** The atlases. */
  atlases: Record<string, AtlasDto>;
}

/** The client data of one world folder. */
export interface WorldFolderDto {
  /** The continents of `.wld.cnt`. */
  continents: ContinentDef[];
  /** The client regions. */
  regions: ClientRegion[];
  /** The `.wld` settings. */
  settings: WorldSettingsDto;
}

/** One world-map texture and its world rectangle (`WORLD_MAPS`, a code table). */
export interface WorldMapRow {
  /** The continent (`ContinentDef.id`) shown on this map; `null` for map 0. */
  continent: number | null;
  /** The map number 0..=7. */
  map: number;
  /** `[x1, z1, x2, z2]` in world coordinates; the screen z axis is inverted. */
  rect: [number, number, number, number];
  /** The texture as a canonical VFS path (`theme/world_*.dds`). */
  texture: string;
}

/** One `World.inc` entry. */
export interface WorldRow {
  /** The define name. */
  define: string;
  /** The world folder as written. */
  folder: string;
  /** `WI_*`. */
  id: number;
  /** The folder exists and has a `.wld` (the 51 worlds the server loads). */
  loadable: boolean;
  /** The display title (`""` for `WI_WORLD_QUIZ`). */
  title: string;
}

/** The `.wld` settings of one folder the client needs. */
export interface WorldSettingsDto {
  /** Indoor ambient colour. */
  ambient: number;
  /** `BGM_*` of the world (0 = the default). */
  bgm: number;
  /** Cloud textures, same order. */
  cloud: (string | null)[];
  /** Indoor diffuse colour. */
  diffuse: number;
  /** Flying allowed. */
  fly: boolean;
  /** Fog start, end and density. */
  fog: [number, number, number];
  /** Indoor world: no sky, no weather, fixed light. */
  indoor: boolean;
  /** The 24 hourly light entries (`r1 g1 b1 r2 g2 b2`) when `use24light`. */
  light24: number[][] | null;
  /** Indoor light direction. */
  light_dir: [number, number, number];
  /** The moon texture (`weather/`), `null` = built-in. */
  moon: string | null;
  /** Metres per unit: the land edge is 128 x `mpu` world units. */
  mpu: number;
  /** Default region attribute flags of the whole world. */
  pk_mode: number;
  /** Lands in x and z. */
  size: [number, number];
  /** Sky textures `[day, evening, night]` as canonical paths under `weather/`; `null` = the built-in one. */
  sky: (string | null)[];
  /** The sun texture (`weather/`), `null` = built-in. */
  sun: string | null;
}

/** `worlds`: the world list, the client data of each folder, the world-map code table and the map records. */
export interface WorldsBundle {
  /** The client data per world folder (lower-case folder name). */
  folders: Record<string, WorldFolderDto>;
  /** The monster records of the 7 continent maps. */
  map_monsters: MapMonsterDto[];
  /** The rainbow race markers. */
  rainbow_markers: RainbowMarkerDto[];
  /** The 8 world-map textures with their rectangles. */
  world_maps: WorldMapRow[];
  /** `World.inc` in id order. */
  worlds: WorldRow[];
}

